def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))
    merged = [list(sorted_intervals[0])]

    for i in range(1, len(sorted_intervals)):
        start, end = sorted_intervals[i]
        last_start, last_end = merged[-1]
        if start <= last_end:
            merged[-1][1] = max(last_end, end)
        else:
            merged.append([start, end])

    return merged

import heapq


def toposort(nodes, edges):
    unique_edges = set(edges)

    adj = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for src, dst in unique_edges:
        adj[src].append(dst)
        in_degree[dst] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected in graph")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit must be positive")
    batches = []
    current = []
    current_sum = 0
    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("weight must be positive and <= limit")
        if current_sum + weight > limit:
            batches.append(current)
            current = []
            current_sum = 0
        current.append(name)
        current_sum += weight
    if current:
        batches.append(current)
    return batches

import re


def parse_env(text):
    result = {}
    key_re = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')

    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError(f"Invalid line (missing '='): {line!r}")
        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()
        if not key_re.fullmatch(key):
            raise ValueError(f"Invalid key: {key!r}")
        if len(value) >= 2 and value[0] == value[-1] and value[0] in ('"', "'"):
            value = value[1:-1]
        result[key] = value

    return result

def parse_sse(chunks):
    raw = b''.join(chunks)
    text = raw.decode('utf-8')
    text = text.replace('\r\n', '\n')
    lines = text.split('\n')

    events = []
    data_lines = []

    for line in lines:
        if line == '':
            if data_lines:
                data = '\n'.join(data_lines)
                if data == '[DONE]':
                    return events
                events.append(data)
            data_lines = []
        elif line.startswith(':'):
            continue
        elif line.startswith('data:'):
            value = line[5:]
            if value.startswith(' '):
                value = value[1:]
            data_lines.append(value)
        else:
            continue

    return events

import math


def retry_delay(attempt, base, cap):
    """Return min(cap, base * 2**attempt) as a float.

    Raises ValueError for negative arguments.
    Handles extremely large attempt values without constructing huge integers.
    """
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("attempt, base, and cap must be nonnegative")

    if base == 0 or cap == 0:
        return 0.0

    # base > 0 and cap > 0 here.
    # Use logarithms to decide whether base * 2**attempt >= cap
    # without ever constructing 2**attempt.
    # log2(base * 2**attempt) == log2(base) + attempt  (exact for integer attempt)
    if math.log2(base) + attempt >= math.log2(cap):
        return float(cap)

    # Here base * 2**attempt < cap (up to ~1 ulp of log precision),
    # so the result is finite and ldexp won't overflow.
    # math.ldexp shifts the exponent directly — no intermediate huge integer.
    return float(math.ldexp(base, attempt))

def fifo_admit(active, queued, budget, slots):
    for item in queued:
        if item > budget:
            raise ValueError(
                f"Reservation {item} exceeds the whole budget {budget}"
            )

    available_budget = budget - sum(active)
    available_slots = slots - len(active)

    admitted = []
    for item in queued:
        if available_budget >= item and available_slots >= 1:
            admitted.append(item)
            available_budget -= item
            available_slots -= 1
        else:
            break

    remaining = queued[len(admitted):]
    return (admitted, remaining)
